while let s = readLine() {
  var n = Int(s)!
  var i = 0
  while n > 999 {
    i += 1
    n /= 1024
  }
  let t = String(n)
  print(
    "\(t.first!)" + String(repeatElement("0", count: t.count - 1))
      + [" B", " KiB", " MiB", " GiB"][i])
}
